  ["roadmap", "\"$HORIZON_BIN\" roadmap list --focus AJCR.review-plan --json"],
  ["inbox", "\"$HORIZON_BIN\" inbox list --status open --json"],
  ["tasks", "\"$HORIZON_BIN\" task list --json"]
];
