  ["issues", "\"$HORIZON_BIN\" inbox list --status open --kind issue --json 2>/dev/null | jq '[.items[]|{id,owner_task,project,title,updated_at,labels}]'"],
  ["convos", "\"$HORIZON_BIN\" inbox list --status open --kind conversation --json 2>/dev/null | jq '[.items[]|{id,owner_task,project,title,updated_at,labels}]'"],
  ["ps", "\"$HORIZON_BIN\" ps 2>&1"]
];
const rs = await Promise.all(cmds.map(async ([k,cmd]) => [k, await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:10000})]));
for (const [k,r] of rs) text(`=== ${k} ===\n${r.output}`);

